### Result
{
  "acceptVisible": true,
  "acceptEnabled": true,
  "stoppedBeforeTouchID": true
}
### Ran Playwright code
```js
await page.evaluate('()=>{const dialog=document.querySelector(\'dialog[open]\');if(document.documentElement.scrollWidth>innerWidth||dialog.scrollWidth>dialog.clientWidth)throw Error(\'Real flow overflow\');const accept=[...dialog.querySelectorAll(\'button\')].find(b=>b.textContent===\'Accept\');return {acceptVisible:!!accept,acceptEnabled:accept?!accept.disabled:false,stoppedBeforeTouchID:true};}');
```

